list.command:
make -pRrq : 2>/dev/null | awk '
/^MAKEFILE_LIST :?= / { mk = $0; sub(/^[^=]*= */, "", mk) }
/^# Files/ { files = 1 }
/^# Finished Make data base/ { files = 0 }
/^# Not a target:/ { skip = 1; next }
files && /^[^#\t]/ { if (!skip && !/^[.%]/) { sub(/:.*/, ""); t[++n] = $0 } skip = 0 }
END {
  m = split(mk, f, " ")
  for (i = 1; i <= m; i++) while ((getline l < f[i]) > 0) if (l ~ /^[^#\t][^:=]*:.*## /) {
    s = l; sub(/.*## */, "", s); gsub(/\\/, "\\\\", s); gsub(/"/, "\\\"", s)
    sub(/:.*/, "", l); k = split(l, ts, " "); for (j = 1; j <= k; j++) d[ts[j]] = s
  }
  for (i = 1; i <= n; i++) printf "{\"target\":\"%s\",\"description\":\"%s\"}\n", t[i], d[t[i]]
}' | sort
